// service-worker.js — مخبز بريدنج | Breading Bakery
// إصدار الكاش: غيّر الرقم ده مع كل تحديث حقيقي للموقع عشان يوصل للمستخدمين
const CACHE_VERSION = "breading-v1";
const SHELL_CACHE = `${CACHE_VERSION}-shell`;
const RUNTIME_CACHE = `${CACHE_VERSION}-runtime`;

// الملفات الأساسية اللي لازم تتخزن عشان الموقع يفتح Offline
const SHELL_FILES = [
  "./",
  "./index.html",
  "./manifest.json",
];

// تثبيت الـ Service Worker وتخزين ملفات الواجهة الأساسية
self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(SHELL_FILES))
  );
  self.skipWaiting();
});

// تنظيف أي كاش قديم من إصدارات سابقة
self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys
          .filter((key) => key.startsWith("breading-") && key !== SHELL_CACHE && key !== RUNTIME_CACHE)
          .map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

// اتصال Firestore/Firebase لازم يفضل رايح للنت مباشرة، الـ Service Worker منزلش عليه
function isFirebaseRequest(url) {
  return (
    url.hostname.includes("firestore.googleapis.com") ||
    url.hostname.includes("firebaseapp.com") ||
    url.hostname.includes("googleapis.com") ||
    url.hostname.includes("gstatic.com") && url.pathname.includes("firebasejs")
  );
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // سيب طلبات Firebase تروح للشبكة عادي زي ما هي (الـ SDK نفسه بيعمل offline persistence)
  if (isFirebaseRequest(url)) return;

  // فتح الصفحة نفسها: جرّب الشبكة الأول عشان تجيب آخر تحديث، ولو مفيش نت رجّع النسخة المخزّنة
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const clone = response.clone();
          caches.open(SHELL_CACHE).then((cache) => cache.put("./index.html", clone));
          return response;
        })
        .catch(() => caches.match("./index.html"))
    );
    return;
  }

  // باقي الملفات (خطوط، أيقونات، ستايل...): كاش الأول، ولو مش موجود جيبه من النت وخزّنه
  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request)
        .then((response) => {
          if (response && response.status === 200 && response.type !== "opaque") {
            const clone = response.clone();
            caches.open(RUNTIME_CACHE).then((cache) => cache.put(request, clone));
          }
          return response;
        })
        .catch(() => cached);
    })
  );
});

// استقبال إشعارات Push (يحتاج ربط Firebase Cloud Messaging وإرسال من سيرفر/Cloud Function)
self.addEventListener("push", (event) => {
  let data = { title: "مخبز بريدنج", body: "عندك تحديث جديد" };
  try {
    if (event.data) data = event.data.json();
  } catch (e) {
    data.body = event.data ? event.data.text() : data.body;
  }
  event.waitUntil(
    self.registration.showNotification(data.title || "مخبز بريدنج", {
      body: data.body || "",
      icon: "data:image/png;base64,",
      badge: "data:image/png;base64,",
      dir: "rtl",
      lang: "ar",
      data: { url: data.url || "./index.html" },
    })
  );
});

// الضغط على الإشعار يفتح الموقع
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetUrl = (event.notification.data && event.notification.data.url) || "./index.html";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if (client.url.includes("index.html") && "focus" in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow(targetUrl);
    })
  );
});
